type State { values: Map[Str, Str], order: List[Str], out: List[Str] }

fn touch(order: List[Str], key: Str) -> List[Str] {
  return order.filter(fn(k) => k != key).push(key)
}

fn put_op(st: State, capacity: Int, key: Str, value: Str) -> State {
  if capacity <= 0 {
    return st
  }
  let is_new = not st.values.has(key)
  let needs_room = is_new and (st.values.len() >= capacity)
  let victim = st.order.first().unwrap_or("")
  let kept_values = match needs_room {
    true => st.values.remove(victim),
    false => st.values,
  }
  let kept_order = match needs_room {
    true => st.order.filter(fn(k) => k != victim),
    false => st.order,
  }
  return State { values: kept_values.set(key, value), order: touch(kept_order, key), out: st.out }
}

fn get_op(st: State, key: Str) -> State {
  let hit = st.values.has(key)
  let shown = st.values.get(key).unwrap_or("-")
  let order2 = match hit {
    true => touch(st.order, key),
    false => st.order,
  }
  return State { values: st.values, order: order2, out: st.out.push(shown) }
}

fn step(st: State, op: Str, capacity: Int) -> State {
  let parts = op.split(" ")
  let cmd = parts.get_or(0, "")
  let key = parts.get_or(1, "")
  if cmd == "put" {
    return put_op(st: st, capacity: capacity, key: key, value: parts.get_or(2, ""))
  }
  return get_op(st: st, key: key)
}

pub fn lru(capacity: Int, ops: List[Str]) -> List[Str] {
  let no_values: Map[Str, Str] = Map {}
  let no_keys: List[Str] = []
  let no_out: List[Str] = []
  let start = State { values: no_values, order: no_keys, out: no_out }
  let end_state = ops.fold(start, fn(st, op) => step(st, op, capacity))
  return end_state.out
}
